<script setup>
import {ref,onUnmounted} from 'vue';import {Head,Link,useForm,router} from '@inertiajs/vue3';import QRCode from 'qrcode';import FamilyLayout from '@/Layouts/FamilyLayout.vue';import {useFamilyCopy} from '@/lib/family';
const p=defineProps({child:Object,range:Object,attendance:Array,care:Array,incidents:Array,invoices:Array,tasks:Array,absences:Array,messages:Array,can_view_billing:Boolean,can_request_pickup:Boolean});const{l,t}=useFamilyCopy();
const tab=ref('care');const tabs=[['care','اليوم','Today'],['messages','الرسائل','Messages'],['billing','الرسوم','Fees'],['planning','المتابعة','Planning']];
const message=useForm({body:''});const absence=useForm({starts_on:'',ends_on:'',reason:''});const rangeForm=useForm({...p.range});
function send(){message.post(`/family/children/${p.child.id}/messages`,{preserveScroll:true,onSuccess:()=>message.reset()});}
const qr=ref(''),qrError=ref(''),qrUntil=ref('');let timer;
async function pickup(){qrError.value='';try{const{data}=await window.axios.post(`/family/children/${p.child.id}/pickup-token`);qr.value=await QRCode.toDataURL(`nursery-pickup:v1:${data.token}`,{width:256,margin:3});qrUntil.value=data.expires_at;clearTimeout(timer);timer=setTimeout(()=>qr.value='',120000);}catch{qrError.value=l('تعذر إنشاء الرمز. راجع صلاحية الاستلام مع الحضانة.','Could not create a code. Check pickup authorization with the nursery.');}}
onUnmounted(()=>clearTimeout(timer));
function ack(id){if(confirm(l('أؤكد أنني قرأت وصف الحادثة. الإقرار لا يغيّر السجل ولا يحل محل التواصل مع الحضانة.','I confirm I have read this incident. Acknowledgment does not change the record or replace speaking with the nursery.')))router.post(`/family/children/${p.child.id}/incidents/${id}/acknowledge`,{confirmed:true},{preserveScroll:true});}
</script>
<template><Head :title="child.name"><meta name="robots" content="noindex,nofollow"/></Head><FamilyLayout><Link href="/family" class="family-text-link">{{l('كل الأطفال','All children')}}</Link><div class="family-heading"><h1>{{child.name}}</h1><p class="family-muted">{{l('ما تشاركه الحضانة معك، في مكان واحد.','What your nursery shares with you, in one place.')}}</p></div><nav class="family-tabs"><button v-for="a in tabs" :key="a[0]" :class="{active:tab===a[0]}" @click="tab=a[0]">{{l(a[1],a[2])}}</button></nav>
<div v-if="tab==='care'"><form class="family-card family-range" @submit.prevent="rangeForm.get(`/family/children/${child.id}`,{preserveScroll:true})"><label>{{l('من','From')}}<input v-model="rangeForm.from" type="date" required/></label><label>{{l('إلى','To')}}<input v-model="rangeForm.to" type="date" required/></label><button class="family-primary">{{l('عرض','Apply')}}</button><p v-for="e in rangeForm.errors" :key="e" class="family-error">{{e}}</p></form><h2 class="family-section-title">{{l('يوميات شاركتها الحضانة','Shared care updates')}}</h2><article class="family-card mb-4" v-for="log in care" :key="log.id"><h2>{{log.date}}</h2><dl class="family-detail-grid"><template v-for="key in ['meals','naps','mood','activities','notes']" :key="key"><div v-if="log[key]"><dt>{{t({meals:'Meals',naps:'Naps',mood:'Mood',activities:'Activities',notes:'Notes'}[key])}}</dt><dd class="family-copy">{{log[key]}}</dd></div></template></dl></article><p v-if="!care.length" class="family-muted">{{l('لم تشارك الحضانة يوميات في هذه الفترة بعد.','No care updates have been shared for this range yet.')}}</p><h2 class="family-section-title">{{l('الحضور المسجل','Recorded attendance')}}</h2><div class="family-card"><div v-for="a in attendance" :key="a.date" class="family-ledger"><strong>{{a.date}}</strong><p>{{l('حضور','Arrival')}}: <span dir="ltr">{{a.check_in_at||'—'}}</span></p><p>{{l('استلام','Pickup')}}: <span dir="ltr">{{a.check_out_at||'—'}}</span></p></div><p v-if="!attendance.length">{{l('لا توجد سجلات في الفترة.','No records in this range.')}}</p></div><h2 class="family-section-title">{{l('الحوادث المشتركة','Shared incidents')}}</h2><article v-for="i in incidents" :key="i.id" class="family-card mb-4"><small>{{i.occurred_at}} · {{t(i.severity)}}</small><p class="family-copy">{{i.description}}</p><p v-if="i.acknowledged" class="family-success">{{l('تم إقرارك بالاطلاع','You acknowledged this incident')}}</p><button v-else class="family-secondary" @click="ack(i.id)">{{l('قرأت هذه الحادثة','I have read this incident')}}</button></article></div>
<section v-if="tab==='messages'" class="family-card"><h2>{{l('حديث مع الحضانة','Talk to the nursery')}}</h2><p class="family-muted">{{l('هذه محادثة حسابك فقط مع إدارة الحضانة. ليست قناة طوارئ.','This conversation is between your account and nursery management. It is not an emergency channel.')}}</p><div v-for="m in messages" :key="m.id" class="family-message" :class="{team:m.staff_id}"><small>{{m.staff_id?l('فريق الحضانة','Nursery team'):l('أنت','You')}} · {{m.created_at}}</small><p class="family-copy">{{m.body}}</p></div><form class="family-form" @submit.prevent="send"><label>{{l('رسالتك','Your message')}}<textarea v-model="message.body" maxlength="4000" rows="4" required/></label><p v-for="e in message.errors" :key="e" class="family-error">{{e}}</p><button class="family-primary" :disabled="message.processing">{{l('إرسال للحضانة','Send to nursery')}}</button></form></section>
<div v-if="tab==='billing'"><p v-if="!can_view_billing" class="family-card">{{l('لم تمنح الحضانة هذا الحساب صلاحية الاطلاع على الرسوم.','The nursery has not enabled billing access for this account.')}}</p><template v-else><p class="family-muted">{{l('دفعات مسجلة، وليست إثبات تحويل بنكي. لا يتم تحصيل أموال من هذه الصفحة.','Recorded payments are not proof of a bank transfer. This page does not collect money.')}}</p><article v-for="i in invoices" :key="i.id" class="family-card mb-4"><h2>{{l('فاتورة','Invoice')}} #{{i.id}}</h2><p>{{i.description}}</p><dl class="family-detail-grid"><div><dt>{{l('المبلغ','Amount')}}</dt><dd dir="ltr">{{i.amount}}</dd></div><div><dt>{{l('المتبقي','Outstanding')}}</dt><dd dir="ltr">{{i.outstanding}}</dd></div><div><dt>{{l('الاستحقاق','Due')}}</dt><dd>{{i.due_date}}</dd></div><div><dt>{{l('الحالة','Status')}}</dt><dd>{{t(i.status)}}</dd></div></dl><p v-for="v in i.payments" :key="v.id" class="family-ledger">{{l('إيصال دفعة مسجلة','Recorded payment receipt')}} #{{v.id}} · {{v.paid_at}} · <b dir="ltr">{{v.amount}}</b></p></article><p v-if="!invoices.length">{{l('لا توجد فواتير صادرة.','No issued invoices.')}}</p></template></div>
<div v-if="tab==='planning'"><section v-if="can_request_pickup" class="family-card mb-5"><h2>{{l('رمز استلام مؤقت','Temporary pickup code')}}</h2><p class="family-muted">{{l('صالح لدقيقتين وللمستلم الذي اعتمدته الحضانة فقط. يجب التحقق من الهوية عند الباب.','Valid for two minutes and only for the pickup person approved by the nursery. Physical identity must still be checked at the door.')}}</p><img v-if="qr" :src="qr" :alt="l('رمز استلام مؤقت','Temporary pickup QR')" class="mx-auto" width="256" height="256"/><small v-if="qr">{{qrUntil}}</small><p v-if="qrError" class="family-error">{{qrError}}</p><button class="family-secondary" @click="pickup">{{l('إنشاء رمز جديد','Create a new code')}}</button></section><section class="family-card mb-5"><h2>{{l('مهام الأسرة','Family tasks')}}</h2><div v-for="task in tasks" :key="task.id" class="family-ledger"><strong>{{task.title}}</strong><p>{{task.due_date}}</p><p v-if="task.completed_at">{{l('مكتملة','Completed')}}</p><button v-else class="family-secondary" @click="router.post(`/family/children/${child.id}/tasks/${task.id}/complete`,{},{preserveScroll:true})">{{l('تمت المهمة','Mark complete')}}</button></div><p v-if="!tasks.length" class="family-muted">{{l('لا توجد مهام.','No tasks.')}}</p></section><section class="family-card"><h2>{{l('غياب مخطط','Planned absence')}}</h2><p class="family-muted">{{l('إخطار للحضانة، لا يمحو الحضور الفعلي ولا يلغي الرسوم تلقائياً.','A notice to the nursery. It does not erase attendance or automatically waive fees.')}}</p><form class="family-form" @submit.prevent="absence.post(`/family/children/${child.id}/absences`,{preserveScroll:true,onSuccess:()=>absence.reset()})"><label>{{l('من','From')}}<input v-model="absence.starts_on" type="date" required/></label><label>{{l('إلى','To')}}<input v-model="absence.ends_on" type="date" required/></label><label>{{l('ملاحظة اختيارية','Optional note')}}<textarea v-model="absence.reason" maxlength="500"/></label><p v-for="e in absence.errors" :key="e" class="family-error">{{e}}</p><button class="family-primary" :disabled="absence.processing">{{l('إخطار الحضانة','Notify nursery')}}</button></form><div v-for="a in absences" :key="a.id" class="family-ledger">{{a.starts_on}} · {{a.ends_on}}<p class="family-copy">{{a.reason}}</p></div></section></div></FamilyLayout></template>
